#endif
extern "C" char* openblas_get_config(void);
extern "C" int openblas_get_num_threads(void);
typedef unsigned long long u64;
namespace fs = std::filesystem;
static double now_s() { return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count(); }

// ------------------------------------------------------------------ graph (same hash as the GPU program)
static inline u64 splitmix64(u64 x) {
  x += 0x9e3779b97f4a7c15ULL; x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL; x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
  return x ^ (x >> 31);
}
static inline bool has_edge(u64 seed, u64 thr, uint32_t n, uint32_t i, uint32_t j) {
  if (i == j) return false;
  uint32_t a = i < j ? i : j, b = i < j ? j : i;
  return (splitmix64(seed ^ ((u64)a * n + b)) >> 32) < thr;
}

// ------------------------------------------------------------------ JSON + statistics (same as trianglebench)
static std::string jstr(const std::string& s) {
  std::string o = "\"";
  for (unsigned char c : s) {
    if (c == '"' || c == '\\') { o += '\\'; o += (char)c; }
    else if (c < 0x20) { char b[8]; snprintf(b, sizeof b, "\\u%04x", c); o += b; }
    else o += (char)c;
  }
  return o + "\"";
}
static std::string jnum(double v) { if (!std::isfinite(v)) return "null"; char b[40]; snprintf(b, sizeof b, "%.10g", v); return b; }
static std::string jint(long long v, bool valid = true) { return valid ? std::to_string(v) : "null"; }
static std::string utc_now() { time_t t = time(nullptr); char b[32]; strftime(b, sizeof b, "%Y-%m-%dT%H:%M:%SZ", gmtime(&t)); return b; }
struct Stats { int k = 0; double mean = NAN, sd = NAN, ci95 = NAN, median = NAN, min = NAN, max = NAN, cv = NAN; };
static double t975(int df) {
  static const double t[] = {12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160, 2.145, 2.131,
                             2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056, 2.052, 2.048, 2.045, 2.042};
  return df <= 0 ? NAN : df <= 30 ? t[df - 1] : df <= 60 ? 2.000 : df <= 120 ? 1.980 : 1.960;
}
static Stats stats(std::vector<double> v) {  // non-finite values (e.g. no energy sensor) are ignored
  v.erase(std::remove_if(v.begin(), v.end(), [](double x) { return !std::isfinite(x); }), v.end());
  Stats s; s.k = (int)v.size(); if (v.empty()) return s;
  std::sort(v.begin(), v.end());
  double sum = 0; for (double x : v) sum += x; s.mean = sum / s.k;
  s.median = s.k % 2 ? v[s.k / 2] : 0.5 * (v[s.k / 2 - 1] + v[s.k / 2]); s.min = v.front(); s.max = v.back();
  if (s.k > 1) { double q = 0; for (double x : v) q += (x - s.mean) * (x - s.mean); s.sd = sqrt(q / (s.k - 1)); s.ci95 = t975(s.k - 1) * s.sd / sqrt((double)s.k); s.cv = s.sd / s.mean; }
  return s;
}
static std::string jstats(const Stats& s) {
  return "{\"k\":" + std::to_string(s.k) + ",\"mean\":" + jnum(s.mean) + ",\"sd\":" + jnum(s.sd) + ",\"ci95_halfwidth\":" + jnum(s.ci95) +
         ",\"median\":" + jnum(s.median) + ",\"min\":" + jnum(s.min) + ",\"max\":" + jnum(s.max) + ",\"cv\":" + jnum(s.cv) + "}";
}

// ------------------------------------------------------------------ sysfs helpers
static bool rd_ll(const std::string& p, long long& v) { FILE* f = fopen(p.c_str(), "r"); if (!f) return false; bool ok = fscanf(f, "%lld", &v) == 1; fclose(f); return ok; }
static std::string rd_line(const std::string& p) {
  FILE* f = fopen(p.c_str(), "r"); if (!f) return ""; char b[512] = ""; if (!fgets(b, sizeof b, f)) b[0] = 0; fclose(f);
  std::string s = b; while (!s.empty() && (s.back() == '\n' || s.back() == ' ')) s.pop_back(); return s;
}
static std::vector<std::string> sorted_glob(const std::string& dir, const std::string& prefix) {
  std::vector<std::string> v; std::error_code ec;
  for (auto& e : fs::directory_iterator(dir, ec)) { std::string n = e.path().filename().string(); if (n.rfind(prefix, 0) == 0) v.push_back(e.path().string()); }
  std::sort(v.begin(), v.end()); return v;
}

struct CpuInfo { std::string name, vendor, product, governor, driver, temp_src, energy_src; int logical = 0, cores = 0, sockets = 0, max_mhz = 0; };
static CpuInfo cpu_info() {
  CpuInfo c; std::map<std::string, int> parts; std::string impl;
  FILE* f = fopen("/proc/cpuinfo", "r"); char line[1024];
  while (f && fgets(line, sizeof line, f)) {
    std::string s = line; auto colon = s.find(':'); if (colon == std::string::npos) continue;
    std::string k = s.substr(0, colon), v = s.substr(colon + 1);
    while (!k.empty() && (k.back() == ' ' || k.back() == '\t')) k.pop_back();
    while (!v.empty() && (v.front() == ' ')) v.erase(0, 1); while (!v.empty() && (v.back() == '\n')) v.pop_back();
    if (k == "model name" && c.name.empty()) c.name = v;
    if (k == "vendor_id" && c.vendor.empty()) c.vendor = v;
    if (k == "CPU implementer") impl = v;
    if (k == "CPU part") parts[v]++;
  }
  if (f) fclose(f);
  if (c.name.empty() && !parts.empty()) {  // aarch64: build a name from the core types
    static const std::map<std::string, std::string> arm = {{"0xd85", "Cortex-X925"}, {"0xd87", "Cortex-A725"}, {"0xd4f", "Neoverse-V2"},
      {"0xd40", "Neoverse-V1"}, {"0xd0c", "Neoverse-N1"}, {"0xd49", "Neoverse-N2"}, {"0xd8e", "Neoverse-N3"}, {"0xd84", "Neoverse-V3"},
      {"0xd0b", "Cortex-A76"}, {"0xd08", "Cortex-A72"}, {"0xd03", "Cortex-A53"}};
    for (auto it = parts.rbegin(); it != parts.rend(); ++it) {
      auto a = arm.find(it->first);
      c.name += (c.name.empty() ? "" : " + ") + std::to_string(it->second) + "x " + (a != arm.end() ? a->second : "part " + it->first);
    }
    c.vendor = impl == "0x41" ? "ARM" : "implementer " + impl;
  }
  c.product = rd_line("/sys/class/dmi/id/sys_vendor") + " " + rd_line("/sys/class/dmi/id/product_name");
  std::map<std::pair<long long, long long>, int> core_ids; std::map<long long, int> pkgs;
  for (auto& d : sorted_glob("/sys/devices/system/cpu", "cpu")) {
    long long pk, co; if (!rd_ll(d + "/topology/physical_package_id", pk) || !rd_ll(d + "/topology/core_id", co)) continue;
    c.logical++; core_ids[{pk, co}]++; pkgs[pk]++;
    long long mx; if (rd_ll(d + "/cpufreq/cpuinfo_max_freq", mx)) c.max_mhz = std::max(c.max_mhz, (int)(mx / 1000));
  }
  c.cores = (int)core_ids.size(); c.sockets = (int)pkgs.size();
  c.governor = rd_line("/sys/devices/system/cpu/cpu0/cpufreq/scaling_governor"); c.driver = rd_line("/sys/devices/system/cpu/cpu0/cpufreq/scaling_driver");
  return c;
}

// ------------------------------------------------------------------ CPU telemetry: samples every 100 ms, raw rows go to CSV
struct Window { double dt = 0, energy_j = NAN, dram_j = NAN, watts = NAN; int tmax = -1; unsigned mhz_med = 0, mhz_min = 0, mhz_max = 0;
                long long throttle = -1; std::string energy_src = "none"; size_t nsamples = 0; };
struct Telemetry {
  struct Rapl { std::string path; long long range; };
  struct S { double t, w; int temp; unsigned mhz; long long thr; };
  std::vector<Rapl> pkg, dram; std::vector<std::string> temps, freqs, throttle; std::string temp_src = "none";
  const int period_ms = 100; std::atomic<bool> running{false}; std::thread th; std::vector<S> buf; double t0 = 0; FILE* csv = nullptr;
  std::vector<long long> e0p, e0d;
  void init(FILE* f) {
    csv = f;
    for (auto& z : sorted_glob("/sys/class/powercap", "intel-rapl:")) {  // also used by AMD (amd_energy via powercap) kernels
      long long e, r; std::string name = rd_line(z + "/name");
      if (!rd_ll(z + "/energy_uj", e) || !rd_ll(z + "/max_energy_range_uj", r)) continue;
      if (name.rfind("package", 0) == 0) pkg.push_back({z + "/energy_uj", r});
      else if (name == "dram") dram.push_back({z + "/energy_uj", r});
    }
    for (const char* want : {"coretemp", "k10temp", "zenpower", "acpitz"}) {  // first matching sensor family wins
      for (auto& h : sorted_glob("/sys/class/hwmon", "hwmon")) if (rd_line(h + "/name") == want)
        for (auto& t : sorted_glob(h, "temp")) if (t.size() > 6 && t.compare(t.size() - 6, 6, "_input") == 0) temps.push_back(t);
      if (!temps.empty()) { temp_src = std::string(want) + " (max over sensors)"; break; }
    }
    for (auto& d : sorted_glob("/sys/devices/system/cpu", "cpu")) {
      if (fs::exists(d + "/cpufreq/scaling_cur_freq")) freqs.push_back(d + "/cpufreq/scaling_cur_freq");
      long long pk; if (fs::exists(d + "/thermal_throttle/package_throttle_count") && rd_ll(d + "/topology/physical_package_id", pk) &&
                        (size_t)pk == throttle.size()) throttle.push_back(d + "/thermal_throttle/package_throttle_count");
    }
    if (csv) fprintf(csv, "n,phase,method,repeat,t_s,power_w,temp_c,cpu_mhz,package_throttle_count\n");
  }
  bool energy_ok() const { return !pkg.empty(); }
  static long long sum(const std::vector<Rapl>& v, std::vector<long long>* each = nullptr) {
    long long s = 0; if (each) each->clear();
    for (auto& r : v) { long long e = 0; rd_ll(r.path, e); s += e; if (each) each->push_back(e); }
    return s;
  }
  static double delta_j(const std::vector<Rapl>& v, const std::vector<long long>& a, const std::vector<long long>& b) {
    double j = 0; for (size_t i = 0; i < v.size(); i++) { long long d = b[i] - a[i]; if (d < 0) d += v[i].range; j += d / 1e6; } return j;
  }
  S sample(std::vector<long long>& last, double& tlast) {
    S x{now_s() - t0, NAN, -1, 0, -1};
    if (energy_ok()) { std::vector<long long> e; sum(pkg, &e); if (!last.empty() && x.t - tlast > 0.02) x.w = delta_j(pkg, last, e) / (x.t - tlast); last = e; tlast = x.t; }
    for (auto& t : temps) { long long v; if (rd_ll(t, v)) x.temp = std::max(x.temp, (int)(v / 1000)); }
    std::vector<unsigned> f; for (auto& p : freqs) { long long v; if (rd_ll(p, v)) f.push_back((unsigned)(v / 1000)); }
    if (!f.empty()) { std::nth_element(f.begin(), f.begin() + f.size() / 2, f.end()); x.mhz = f[f.size() / 2]; }
    if (!throttle.empty()) { x.thr = 0; for (auto& p : throttle) { long long v = 0; rd_ll(p, v); x.thr += v; } }
    return x;
  }
  void start() {
    buf.clear(); t0 = now_s(); sum(pkg, &e0p); sum(dram, &e0d); running = true;
    th = std::thread([this] { std::vector<long long> last = e0p; double tl = 0;
      while (running) { buf.push_back(sample(last, tl)); std::this_thread::sleep_for(std::chrono::milliseconds(period_ms)); } });
  }
  Window stop(int n, const char* phase, const char* method, int rep) {
    Window w; running = false; th.join(); w.dt = now_s() - t0; w.nsamples = buf.size();
    std::vector<long long> e1p, e1d; sum(pkg, &e1p); sum(dram, &e1d);
    if (energy_ok()) { w.energy_j = delta_j(pkg, e0p, e1p); w.energy_src = "rapl_package_energy_counter"; w.watts = w.energy_j / w.dt; }
    if (!dram.empty()) w.dram_j = delta_j(dram, e0d, e1d);
    std::vector<unsigned> mhz;
    for (auto& x : buf) {
      w.tmax = std::max(w.tmax, x.temp); if (x.mhz) mhz.push_back(x.mhz);
      if (csv) fprintf(csv, "%d,%s,%s,%d,%.3f,%s,%d,%u,%s\n", n, phase, method, rep, x.t, jnum(x.w).c_str(), x.temp, x.mhz, jint(x.thr, x.thr >= 0).c_str());
    }
    if (!mhz.empty()) { std::sort(mhz.begin(), mhz.end()); w.mhz_med = mhz[mhz.size() / 2]; w.mhz_min = mhz.front(); w.mhz_max = mhz.back(); }
    if (buf.size() > 1 && buf.front().thr >= 0) w.throttle = buf.back().thr - buf.front().thr;
    return w;
  }
};

// ------------------------------------------------------------------ the two CPU methods (one graph size)
static const char* NAMES[2] = {"C1 CPU cores  INT64 bitset+popcnt", "C2 CPU cores  FP32 GEMM (BLAS)   "};
static const char* IDS[2] = {"C1_cpu_int64_bitset_popc", "C2_cpu_fp32_gemm_blas"};
struct Ctx {
  int n, W; u64 seed, thr; std::vector<u64> bits; std::vector<float> a32, c32; std::vector<u64> rowsum[2];
  void init(int n_, double p, u64 seed_) {
    n = n_; W = n / 64; seed = seed_; thr = (u64)llround(p * 4294967296.0);
    bits.assign((size_t)n * W, 0); a32.assign((size_t)n * n, 0.f); c32.assign((size_t)n * n, 0.f);
    for (auto& r : rowsum) r.assign(n, 0);
#pragma omp parallel for schedule(static)
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++) if (has_edge(seed, thr, n, i, j)) { bits[(size_t)i * W + j / 64] |= 1ull << (j % 64); a32[(size_t)i * n + j] = 1.f; }
  }
  inline u64 bit(int i, int j) const { return (bits[(size_t)i * W + (j >> 6)] >> (j & 63)) & 1ull; }
  void solve(int m) {
    if (m == 0) {
      // C1: 32-row i tiles over threads, 256-row j tiles stay in L2, 4x4 register block of popcounts
#pragma omp parallel for schedule(dynamic, 1)
      for (int bi = 0; bi < n; bi += 32) {
        u64 acc[32] = {};
        for (int bj = 0; bj < n; bj += 256)
          for (int i = bi; i < bi + 32; i += 4)
            for (int j = bj; j < bj + 256; j += 4) {
              const u64 *a0 = &bits[(size_t)i * W], *a1 = a0 + W, *a2 = a1 + W, *a3 = a2 + W;
              const u64 *b0 = &bits[(size_t)j * W], *b1 = b0 + W, *b2 = b1 + W, *b3 = b2 + W;
              uint32_t c[4][4] = {};
              for (int k = 0; k < W; k++) {
                const u64 a[4] = {a0[k], a1[k], a2[k], a3[k]}, b[4] = {b0[k], b1[k], b2[k], b3[k]};
                for (int r = 0; r < 4; r++) for (int q = 0; q < 4; q++) c[r][q] += (uint32_t)__builtin_popcountll(a[r] & b[q]);
              }
              for (int r = 0; r < 4; r++) for (int q = 0; q < 4; q++) acc[i - bi + r] += c[r][q] * bit(i + r, j + q);
            }
        for (int r = 0; r < 32; r++) rowsum[0][bi + r] = acc[r];
      }
    } else {
      cblas_sgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans, n, n, n, 1.f, a32.data(), n, a32.data(), n, 0.f, c32.data(), n);
#pragma omp parallel for schedule(static)
      for (int i = 0; i < n; i++) { u64 s = 0; const float* c = &c32[(size_t)i * n]; for (int j = 0; j < n; j++) s += bit(i, j) * (u64)c[j]; rowsum[1][i] = s; }
    }
  }
};
static u64 total(const std::vector<u64>& rs) { u64 s = 0; for (u64 x : rs) s += x; return s / 6; }

static std::vector<u64> cpu_reference(int n, u64 seed, u64 thr) {  // brute force over all node triples
  std::vector<uint8_t> A((size_t)n * n);
  for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) A[(size_t)i * n + j] = has_edge(seed, thr, n, i, j);
  std::vector<u64> t(n, 0);
  for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (A[(size_t)i * n + j])
    for (int k = j + 1; k < n; k++) if (A[(size_t)i * n + k] && A[(size_t)j * n + k]) { t[i] += 2; t[j] += 2; t[k] += 2; }
  return t;
}
static int selftest() {
  struct Case { int n; double p; u64 seed; } cases[] = {{512, 0.5, 1}, {1024, 0.1, 2}, {768, 1.0, 3}, {256, 0.0, 4}, {1280, 0.3, 5}};
  int fails = 0;
  for (auto& c : cases) {
    Ctx x; x.init(c.n, c.p, c.seed);
    std::vector<u64> ref = cpu_reference(c.n, c.seed, x.thr);
    printf("selftest n=%5d p=%.2f : brute force %10llu triangles |", c.n, c.p, total(ref));
    bool ok = true;
    for (int m = 0; m < 2; m++) { x.solve(m); bool eq = x.rowsum[m] == ref; ok &= eq; printf(" C%d %s", m + 1, eq ? "OK" : "FAIL"); }
    if (c.p == 1.0) { u64 exp = (u64)c.n * (c.n - 1) * (c.n - 2) / 6; bool eq = total(ref) == exp; ok &= eq; printf(" | C(n,3) %s", eq ? "OK" : "FAIL"); }
    printf("\n"); fails += !ok;
  }
  printf("selftest: %s\n", fails ? "FAILED" : "PASSED");
  return fails ? 1 : 0;
}

static void usage() {
  printf("trianglebench-cpu %s - triangle counting on the CPU (OpenMP bitset kernel vs. BLAS FP32 GEMM)\n"
         "usage: trianglebench-cpu [options]\n"
         "  --n LIST      node counts, multiples of 256, comma separated (default 4096)\n"
         "  --p P         edge probability (default 0.5)\n"
         "  --seed S      graph seed (default 1)\n"
         "  --seconds T   measuring window per method and repetition (default 5)\n"
         "  --repeats R   repetitions per graph size (default 5); method order alternates every repetition\n"
         "  --warmup T    warm-up seconds per graph size (default 5)\n"
         "  --cooldown T  idle seconds before every measuring window (default 0)\n"
         "  --label TEXT  free text stored in the result file, e.g. system name or settings\n"
         "  --out PREFIX  writes PREFIX.json and PREFIX.telemetry.csv (default tbcpu_<host cpu>_<utc time>)\n"
         "  --selftest    compare both methods with a brute-force count and exit\n"
         "threads: OMP_NUM_THREADS / OPENBLAS_NUM_THREADS (default: all logical CPUs); energy needs read access to RAPL\n", VERSION);
}

int main(int argc, char** argv) {
  std::vector<int> sizes{4096}; double p = 0.5, secs = 5, warm = 5, cool = 0; int reps = 5; u64 seed = 1; bool st = false;
  std::string label, out, argline;
  for (int i = 0; i < argc; i++) { std::string a = argv[i]; if (a.find(' ') != std::string::npos) a = "'" + a + "'"; argline += (i ? " " : "") + a; }
  for (int i = 1; i < argc; i++) {
    std::string a = argv[i]; auto val = [&] { if (i + 1 >= argc) { usage(); exit(2); } return std::string(argv[++i]); };
    if (a == "--n") { sizes.clear(); std::string v = val(); for (size_t q = 0, e; q < v.size(); q = e + 1) { e = v.find(',', q); if (e == std::string::npos) e = v.size(); sizes.push_back(atoi(v.substr(q, e - q).c_str())); } }
    else if (a == "--p") p = atof(val().c_str()); else if (a == "--seed") seed = strtoull(val().c_str(), 0, 10);
    else if (a == "--seconds") secs = atof(val().c_str()); else if (a == "--repeats") reps = atoi(val().c_str());
    else if (a == "--warmup") warm = atof(val().c_str()); else if (a == "--cooldown") cool = atof(val().c_str());
    else if (a == "--label") label = val(); else if (a == "--out") out = val(); else if (a == "--selftest") st = true;
    else { usage(); return a == "--help" || a == "-h" ? 0 : 2; }
  }
  CpuInfo ci = cpu_info();
  struct utsname un; uname(&un);
  const int threads = omp_get_max_threads();
  printf("trianglebench-cpu %s (%s) | %s | %d logical CPUs, %d cores, %d socket(s), max %d MHz | %d OpenMP threads, %d BLAS threads | %s %s\n",
         VERSION, GIT_COMMIT, ci.name.c_str(), ci.logical, ci.cores, ci.sockets, ci.max_mhz, threads, openblas_get_num_threads(), un.sysname, un.machine);
  printf("BLAS: %s\n", openblas_get_config());
  if (st) return selftest();
  if (p < 0 || p > 1 || reps < 1 || secs <= 0) { fprintf(stderr, "invalid --p, --repeats or --seconds\n"); return 2; }
  const double mem_total = (double)sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE), mem_avail = (double)sysconf(_SC_AVPHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
  for (int n : sizes) {
    if (n < 256 || n % 256 || n >= (1 << 24)) { fprintf(stderr, "invalid --n %d (multiple of 256 required)\n", n); return 2; }
    double need = 8.0 * n * n + (200 << 20);
    if (need > mem_avail) { fprintf(stderr, "n=%d needs %.1f GB RAM, %.1f GB free - use a smaller --n\n", n, need / 1e9, mem_avail / 1e9); return 2; }
  }
  std::string tag; for (char c : ci.name) tag += isalnum((unsigned char)c) ? (char)tolower(c) : '-';
  tag = tag.substr(0, 40);
  std::string t_start = utc_now();
  if (out.empty()) { std::string ts = t_start; ts.erase(std::remove(ts.begin(), ts.end(), ':'), ts.end()); ts.erase(std::remove(ts.begin(), ts.end(), '-'), ts.end()); out = "tbcpu_" + tag + "_" + ts; }
  FILE* csv = fopen((out + ".telemetry.csv").c_str(), "w");
  if (!csv) { fprintf(stderr, "cannot write %s.telemetry.csv\n", out.c_str()); return 2; }
  Telemetry tel; tel.init(csv);
  printf("energy: %s%s | temperature: %s | clock: %zu cpufreq files | throttle counters: %zu\n",
         tel.energy_ok() ? "RAPL package" : "unavailable (no RAPL or no read access)", tel.dram.empty() ? "" : " + DRAM",
         tel.temp_src.c_str(), tel.freqs.size(), tel.throttle.size());
  auto env = [](const char* k) { const char* v = getenv(k); return v ? jstr(v) : std::string("null"); };

  std::string J = "{\"schema\":" + jstr(SCHEMA) + ",\"tool\":{\"name\":\"trianglebench-cpu\",\"version\":" + jstr(VERSION) + ",\"git_commit\":" + jstr(GIT_COMMIT) +
    ",\"build_arch\":" + jstr(BUILD_ARCH) + ",\"compiler\":" + jstr(__VERSION__) + ",\"openmp\":" + std::to_string(_OPENMP) + ",\"blas\":" + jstr(openblas_get_config()) +
    ",\"command_line\":" + jstr(argline) + "}";
  J += ",\"label\":" + jstr(label) + ",\"start_utc\":" + jstr(t_start);
  J += ",\"system\":{\"os\":" + jstr(un.sysname) + ",\"kernel\":" + jstr(un.release) + ",\"machine\":" + jstr(un.machine) + ",\"product\":" + jstr(ci.product) +
    ",\"memory_bytes\":" + jnum(mem_total) + "}";
  J += ",\"cpu\":{\"name\":" + jstr(ci.name) + ",\"vendor\":" + jstr(ci.vendor) + ",\"logical_cpus\":" + std::to_string(ci.logical) + ",\"cores\":" + std::to_string(ci.cores) +
    ",\"sockets\":" + std::to_string(ci.sockets) + ",\"max_mhz\":" + jint(ci.max_mhz, ci.max_mhz > 0) + ",\"governor\":" + jstr(ci.governor) + ",\"cpufreq_driver\":" + jstr(ci.driver) +
    ",\"openmp_threads\":" + std::to_string(threads) + ",\"blas_threads\":" + std::to_string(openblas_get_num_threads()) +
    ",\"env\":{\"OMP_NUM_THREADS\":" + env("OMP_NUM_THREADS") + ",\"OMP_PROC_BIND\":" + env("OMP_PROC_BIND") + ",\"OMP_PLACES\":" + env("OMP_PLACES") +
    ",\"OPENBLAS_NUM_THREADS\":" + env("OPENBLAS_NUM_THREADS") + "}}";
  J += ",\"telemetry\":{\"energy_counter\":" + std::string(tel.energy_ok() ? "true" : "false") + ",\"energy_domain\":" + jstr(tel.energy_ok() ? "RAPL package (cores + uncore, without DRAM)" : "none") +
    ",\"dram_energy\":" + (tel.dram.empty() ? "false" : "true") + ",\"temperature_source\":" + jstr(tel.temp_src) +
    ",\"sample_period_ms\":" + std::to_string(tel.period_ms) + ",\"file\":" + jstr(out + ".telemetry.csv") + "}";
  J += ",\"parameters\":{\"p\":" + jnum(p) + ",\"seed\":" + std::to_string(seed) + ",\"seconds\":" + jnum(secs) + ",\"repeats\":" + std::to_string(reps) +
    ",\"warmup_s\":" + jnum(warm) + ",\"cooldown_s\":" + jnum(cool) + ",\"order\":\"alternating: repetition r runs methods (r, r+1) mod 2\"}";
  J += ",\"runs\":[";

  int bad = 0;
  for (size_t si = 0; si < sizes.size(); si++) {
    const int n = sizes[si];
    Ctx x; x.init(n, p, seed);
    const double ops = 2.0 * n * (double)n * n;
    x.solve(1); std::vector<u64> ref = x.rowsum[1];
    double T = (double)total(ref), nc3 = (double)n * (n - 1) * (n - 2) / 6, triples = 0, csum = 0; u64 degsum = 0;
    for (int i = 0; i < n; i++) {
      u64 d = 0; for (int w = 0; w < x.W; w++) d += __builtin_popcountll(x.bits[(size_t)i * x.W + w]);
      degsum += d; triples += 0.5 * (double)d * (d - 1.0); if (d > 1) csum += (ref[i] / 2.0) / (0.5 * (double)d * (d - 1.0));
    }
    double gcc = triples > 0 ? 3 * T / triples : 0.0;
    printf("\ngraph G(n=%d, p=%.4f, seed=%llu): %llu edges, %.0f triangles (theory C(n,3)p^3 = %.0f, ratio %.5f)\n", n, p, seed, degsum / 2, T, nc3 * p * p * p, T / (nc3 * p * p * p));
    printf("clustering: global %.6f, mean local %.6f, theory p = %.6f\n", gcc, csum / n, p);
    { double t0 = now_s(); while (now_s() - t0 < warm) { x.solve(0); x.solve(1); } }

    struct Meas { std::vector<double> solve_s; Window w; bool ok; double tops, s_per_solve, j_per_solve; };
    std::vector<Meas> alone[2];
    for (int r = 0; r < reps; r++) {
      printf("repetition %d/%d ...", r + 1, reps); fflush(stdout);
      for (int q = 0; q < 2; q++) {
        const int m = (r + q) % 2;
        if (cool > 0) std::this_thread::sleep_for(std::chrono::milliseconds((int)(cool * 1000)));
        Meas M; tel.start(); double t0 = now_s(), t = t0;
        while (t - t0 < secs || M.solve_s.size() < 2) { x.solve(m); double t1 = now_s(); M.solve_s.push_back(t1 - t); t = t1; }
        double dt = t - t0; M.w = tel.stop(n, "alone", IDS[m], r + 1);
        M.ok = x.rowsum[m] == ref; bad += !M.ok;
        M.s_per_solve = dt / M.solve_s.size(); M.tops = ops / M.s_per_solve / 1e12; M.j_per_solve = M.w.energy_j / M.solve_s.size();
        alone[m].push_back(M);
      }
      printf(" done\n");
    }

    printf("\nn=%d: %d repetitions x %.0f s, mean +- 95%% CI (Student t). eq.TOPS = 2n^3/time (work of a dense A*A)\n", n, reps, secs);
    printf("%-35s %16s %8s %6s %6s %5s %8s %10s %5s\n", "method", "eq.TOPS", "CV", "W", "T max", "MHz", "TOPS/W", "J/solve", "check");
    J += std::string(si ? "," : "") + "{\"n\":" + std::to_string(n) + ",\"graph\":{\"edges\":" + std::to_string(degsum / 2) + ",\"triangles\":" + std::to_string(total(ref)) +
      ",\"triangles_expected\":" + jnum(nc3 * p * p * p) + ",\"global_clustering_fp64\":" + jnum(gcc) + ",\"mean_local_clustering_fp64\":" + jnum(csum / n) + "}";
    J += ",\"methods\":[";
    for (int m = 0; m < 2; m++) {
      std::vector<double> v_tops, v_s, v_w, v_j, v_tpw, mhz; int tmax = -1; bool ok = true;
      for (auto& M : alone[m]) { v_tops.push_back(M.tops); v_s.push_back(M.s_per_solve); v_w.push_back(M.w.watts); v_j.push_back(M.j_per_solve);
        v_tpw.push_back(M.tops / M.w.watts); tmax = std::max(tmax, M.w.tmax); ok &= M.ok; mhz.push_back(M.w.mhz_med); }
      Stats s_t = stats(v_tops), s_w = stats(v_w), s_j = stats(v_j), s_e = stats(v_tpw);
      printf("%-35s %8.4f +-%6.4f %6.2f%% %6.1f %6d %5.0f %8.4f %10.4g %5s\n", NAMES[m], s_t.mean, s_t.ci95, 100 * s_t.cv, s_w.mean, tmax, stats(mhz).median, s_e.mean, s_j.mean, ok ? "OK" : "FAIL");
      if (m == 0) printf("%-35s native: %.2f G popcnt64/s (AND+POPCNT+ADD per 64-bit word pair)\n", "", (double)n * n * x.W / stats(v_s).mean / 1e9);
      else printf("%-35s native: %.1f GFLOP/s FP32 in sgemm + masked row sum\n", "", s_t.mean * 1e3);
      J += std::string(m ? "," : "") + "{\"id\":" + jstr(IDS[m]) + ",\"verified\":" + (ok ? "true" : "false");
      J += ",\"summary\":{\"eq_tops\":" + jstats(s_t) + ",\"seconds_per_solve\":" + jstats(stats(v_s)) + ",\"watts\":" + jstats(s_w) +
           ",\"joule_per_solve\":" + jstats(s_j) + ",\"eq_tops_per_watt\":" + jstats(s_e) + "},\"repetitions\":[";
      for (size_t r = 0; r < alone[m].size(); r++) {
        auto& M = alone[m][r];
        J += std::string(r ? "," : "") + "{\"repeat\":" + std::to_string(r + 1) + ",\"position_in_order\":" + std::to_string((m - (int)r % 2 + 2) % 2 + 1) +
          ",\"solves\":" + std::to_string(M.solve_s.size()) + ",\"window_s\":" + jnum(M.w.dt) + ",\"seconds_per_solve\":" + jnum(M.s_per_solve) +
          ",\"eq_tops\":" + jnum(M.tops) + ",\"energy_j\":" + jnum(M.w.energy_j) + ",\"dram_energy_j\":" + jnum(M.w.dram_j) + ",\"energy_source\":" + jstr(M.w.energy_src) +
          ",\"watts\":" + jnum(M.w.watts) + ",\"joule_per_solve\":" + jnum(M.j_per_solve) + ",\"temp_max_c\":" + jint(M.w.tmax, M.w.tmax >= 0) +
          ",\"cpu_mhz_median\":" + std::to_string(M.w.mhz_med) + ",\"cpu_mhz_min\":" + std::to_string(M.w.mhz_min) + ",\"cpu_mhz_max\":" + std::to_string(M.w.mhz_max) +
          ",\"thermal_throttle_events\":" + jint(M.w.throttle, M.w.throttle >= 0) + ",\"telemetry_samples\":" + std::to_string(M.w.nsamples) + ",\"solve_s\":[";
        for (size_t k = 0; k < M.solve_s.size(); k++) J += (k ? "," : "") + jnum(M.solve_s[k]);
        J += "]}";
      }
      J += "]}";
    }
    J += "]}";
  }
  J += "],\"end_utc\":" + jstr(utc_now()) + ",\"all_verified\":" + (bad ? "false" : "true") + "}\n";
  fclose(csv);
  FILE* f = fopen((out + ".json").c_str(), "w");
  if (!f || fputs(J.c_str(), f) < 0) { fprintf(stderr, "cannot write %s.json\n", out.c_str()); return 2; }
  fclose(f);
  printf("\nresult: %s\nwritten: %s.json, %s.telemetry.csv\n", bad ? "MISMATCH - results differ between methods" : "both methods agree on every node", out.c_str(), out.c_str());
  return bad ? 1 : 0;
}
